def integer_to_roman(num):
    tokens = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),(50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
    parts = []
    for value, token in tokens:
        while num >= value:
            parts.append(token)
            num -= value
    return "".join(parts)

